<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();
$role=(string)$_SESSION['role'];$uid=(int)$_SESSION['user_id'];if(!in_array($role,['parent','pupil'],true)){http_response_code(403);exit('Holiday packages are available only to linked learners and guardians.');}
$db=db();$packageId=filter_var($_GET['id']??$_POST['package_id']??null,FILTER_VALIDATE_INT);$pupilId=0;$school=0;$pupil=null;$readOnly=$role==='parent';
if($role==='pupil'){$q=$db->prepare("SELECT p.id,p.school_id,p.class_level,p.first_name,p.last_name,p.admission_number,s.name school_name FROM pupil_accounts pa JOIN pupils p ON p.id=pa.pupil_id AND p.school_id=pa.school_id JOIN schools s ON s.id=p.school_id WHERE pa.user_id=? AND pa.active=1 AND p.status='active' LIMIT 1");$q->execute([$uid]);$pupil=$q->fetch();if($pupil){$pupilId=(int)$pupil['id'];$school=(int)$pupil['school_id'];}}
else{$pupilId=(int)($_GET['pupil_id']??$_POST['pupil_id']??0);$q=$db->prepare("SELECT p.id,p.school_id,p.class_level,p.first_name,p.last_name,p.admission_number,s.name school_name FROM pupil_guardians g JOIN pupils p ON p.id=g.pupil_id AND p.school_id=g.school_id JOIN schools s ON s.id=g.school_id WHERE g.guardian_user_id=? AND p.id=? AND p.status='active' LIMIT 1");$q->execute([$uid,$pupilId]);$pupil=$q->fetch();if($pupil){$school=(int)$pupil['school_id'];}}
if(!$pupil){http_response_code(403);exit('No active pupil is linked to this account.');}
$q=$db->prepare("SELECT * FROM holiday_packages WHERE id=? AND school_id=? AND class_id=(SELECT id FROM school_classes WHERE school_id=? AND name=?) AND status='published' AND (available_from IS NULL OR available_from<=CURRENT_DATE) AND (available_until IS NULL OR available_until>=CURRENT_DATE)");$q->execute([$packageId,$school,$school,$pupil['class_level']]);$package=$q->fetch();if(!$package){http_response_code(404);exit('This package is not available for this pupil.');}
$q=$db->prepare('SELECT id,status,pupil_response,teacher_feedback FROM holiday_package_progress WHERE package_id=? AND school_id=? AND pupil_id=?');$q->execute([$packageId,$school,$pupilId]);$progress=$q->fetch();if(!$readOnly&&!$progress){$q=$db->prepare("INSERT IGNORE INTO holiday_package_progress(package_id,school_id,pupil_id,status) VALUES(?,?,?,'assigned')");$q->execute([$packageId,$school,$pupilId]);$q=$db->prepare('SELECT id,status,pupil_response,teacher_feedback FROM holiday_package_progress WHERE package_id=? AND school_id=? AND pupil_id=?');$q->execute([$packageId,$school,$pupilId]);$progress=$q->fetch();}
$error='';$notice='';$async=str_contains((string)($_SERVER['HTTP_ACCEPT']??''),'application/json');
if($_SERVER['REQUEST_METHOD']==='POST'){
 if($readOnly){http_response_code(403);if($async){header('Content-Type: application/json');echo json_encode(['ok'=>false,'message'=>'Parents can view package progress but cannot submit learner work.']);exit;}exit('Parents cannot submit learner work.');}
 if($async){if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??''))){http_response_code(400);header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>false,'message'=>'Your session expired. Reload and try again.']);exit;}}else{verify_csrf();}
 $response=trim((string)($_POST['pupil_response']??''));$state=(string)($_POST['status']??'in_progress');if(!in_array($state,['in_progress','completed'],true)||mb_strlen($response)>100000){$error='Save a response up to 100,000 characters and choose a valid progress state.';}else{try{$db->beginTransaction();$q=$db->prepare('SELECT id,status FROM holiday_package_progress WHERE package_id=? AND school_id=? AND pupil_id=? FOR UPDATE');$q->execute([$packageId,$school,$pupilId]);$current=$q->fetch();if(!$current){$db->prepare("INSERT INTO holiday_package_progress(package_id,school_id,pupil_id,status) VALUES(?,?,?,'assigned')")->execute([$packageId,$school,$pupilId]);$progressId=(int)$db->lastInsertId();}else{$progressId=(int)$current['id'];}$q=$db->prepare("UPDATE holiday_package_progress SET status=IF(status='completed','completed',?),pupil_response=? WHERE id=? AND school_id=?");$q->execute([$state,$response?:null,$progressId,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'save_progress','holiday_package',$packageId,json_encode(['school_id'=>$school,'pupil_id'=>$pupilId,'progress_id'=>$progressId,'status'=>$state],JSON_THROW_ON_ERROR)]);$db->commit();$notice='Your holiday package progress was saved.';$q=$db->prepare('SELECT id,status,pupil_response,teacher_feedback FROM holiday_package_progress WHERE id=?');$q->execute([$progressId]);$progress=$q->fetch();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error='Your progress could not be saved. Please try again.';error_log('Holiday package progress error: '.$e->getMessage());}}
 if($async){http_response_code($error?422:200);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode(['ok'=>$error==='', 'message'=>$error?:$notice,'data'=>['status'=>$progress['status']??'assigned'] ],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
}
$q=$db->prepare('SELECT i.id,i.sequence_no,i.item_type,i.title,i.instructions,i.content,n.content note_content,n.source note_source,n.title note_title,q.prompt question_prompt,q.options_json question_options,q.marks question_marks FROM holiday_package_items i JOIN holiday_packages hp ON hp.id=i.package_id AND hp.school_id=i.school_id JOIN school_classes c ON c.id=hp.class_id AND c.school_id=hp.school_id JOIN school_class_subjects cs ON cs.id=hp.subject_id AND cs.class_id=c.id LEFT JOIN learning_notes n ON n.id=i.learning_note_id AND n.status=\'published\' AND n.class_level=c.name AND (n.subject IS NULL OR n.subject=cs.name) AND (n.note_type=\'central\' OR (n.note_type=\'teacher\' AND n.school_id=hp.school_id)) LEFT JOIN question_bank q ON q.id=i.question_id AND q.school_id=hp.school_id AND q.class_id=hp.class_id AND q.subject_id=hp.subject_id AND q.status=\'published\' WHERE i.package_id=? AND i.school_id=? ORDER BY i.sequence_no');$q->execute([$packageId,$school]);$items=$q->fetchAll();$csrf=csrf_token();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($package['title'])?> · Holiday learning</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/api.js"></script><script defer src="assets/holiday-package-view.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb"><a href="<?=$role==='parent'?'parent_portal.php':'pupil_portal.php'?>">Portal</a> <span>/</span> Holiday learning</div><div class="top-actions"><span class="role-chip"><?=e($role==='parent'?'Parent / Guardian':'Learner')?></span><div class="user-name"><?=e((string)($_SESSION['name']??'User'))?></div></div></header><div class="page-content" data-csrf="<?=e($csrf)?>" data-read-only="<?=$readOnly?'1':'0'?>"><section class="welcome-row"><div><div class="eyebrow"><?=e($pupil['school_name'].' · '.$pupil['class_level'])?></div><h1><?=e($package['title'])?></h1><p class="muted"><?=e($package['subject_id']?'Holiday package':'Learning package')?> · <?=e($package['holiday_period'])?> · <?=e(trim($pupil['first_name'].' '.$pupil['last_name']))?></p><p><?=e($package['introduction']??'')?></p></div><button class="button" type="button" onclick="window.print()">Print / save PDF</button></section><div id="package-view-notice" class="notice <?=($error?'error':'success')?>" role="status" aria-live="polite"<?=$error||$notice?'':' hidden'?>><?=e($error?:$notice)?></div><section class="content-section"><div class="section-heading"><div><div class="eyebrow">PACKAGE CONTENT</div><h2>Learning activities</h2></div><span class="count-pill"><?=count($items)?> items</span></div><?php foreach($items as $item):?><article class="question-card"><div class="eyebrow"><?=e($item['sequence_no'].'. '.ucfirst($item['item_type']))?></div><h3><?=e($item['title'])?></h3><?php if($item['instructions']):?><p><strong>Instructions:</strong> <?=nl2br(e($item['instructions']))?></p><?php endif;?><div class="learner-material-content"><?php if($item['note_content']):?><?=nl2br(e($item['note_content']))?><?php elseif($item['question_prompt']):?><?=nl2br(e($item['question_prompt']))?><?php else:?><?=nl2br(e($item['content']??''))?><?php endif;?></div><?php if($item['question_options']):$options=json_decode((string)$item['question_options'],true)?:[];?><ol type="A"><?php foreach($options as $option):?><li><?=e($option)?></li><?php endforeach;?></ol><?php endif;?><?php if($item['note_source']):?><p class="muted">Source: <?=e($item['note_source'])?></p><?php endif;?></article><?php endforeach;?></section><section class="note-create"><div class="section-heading"><div><div class="eyebrow">MY PROGRESS</div><h2><?=e(ucwords(str_replace('_',' ',$progress['status']??'assigned')))?></h2></div><?php if($progress['teacher_feedback']??null):?><span class="count-pill">Teacher feedback received</span><?php endif;?></div><?php if($progress['teacher_feedback']??null):?><p><?=nl2br(e($progress['teacher_feedback']))?></p><?php endif;?><?php if(!$readOnly):?><form id="package-progress-form" method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="package_id" value="<?=$packageId?>"><input type="hidden" name="pupil_id" value="<?=$pupilId?>"><label for="pupil-response">Your work or reflection</label><textarea id="pupil-response" name="pupil_response" rows="8" maxlength="100000"><?=e((string)($progress['pupil_response']??''))?></textarea><div class="form-grid"><label for="progress-status">Progress</label><select id="progress-status" name="status"><option value="in_progress"<?=$progress['status']==='in_progress'?' selected':''?>>In progress</option><option value="completed"<?=$progress['status']==='completed'?' selected':''?>>Completed</option></select></div><button class="button primary" type="submit">Save progress</button></form><?php else:?><p class="muted">Progress: <?=e(ucwords(str_replace('_',' ',$progress['status']??'assigned')))?></p><?php endif;?></section><footer class="page-footer">ShuleLite <span>·</span> Holiday learning</footer></div></main></div></body></html>
